import{_ as t,o,c as d,ag as a}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"Value Formatting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reference-value-formatting.md","filePath":"guide/reference-value-formatting.md"}'),r={name:"guide/reference-value-formatting.md"};function s(n,e,c,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="value-formatting" tabindex="-1">Value Formatting <a class="header-anchor" href="#value-formatting" aria-label="Permalink to &quot;Value Formatting&quot;">​</a></h1><p>Central formats values with .NET <a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/composite-formatting" target="_blank" rel="noreferrer">composite formatting</a>. Everywhere you can shape how a value is rendered — a parameterized placeholder, a Formatting Template transform, a positional argument in a Read URL — the format you write is passed through to that engine. One syntax covers all of them, and the full Microsoft reference for <a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/standard-date-and-time-format-strings" target="_blank" rel="noreferrer">standard</a> and <a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/custom-date-and-time-format-strings" target="_blank" rel="noreferrer">custom</a> format strings applies verbatim.</p><p>This page is the shared appendix for that syntax. It is referenced from <a href="./datahub-endpoint-config.html#parameterizing">Parameterizing</a> and from the <a href="./datahub-data-adaptation.html#transforms-tab">Formatting Template</a> transform.</p><h2 id="typed-values" tabindex="-1">The one rule that explains most surprises <a class="header-anchor" href="#typed-values" aria-label="Permalink to &quot;The one rule that explains most surprises {#typed-values}&quot;">​</a></h2><p><strong>A format specifier only does something when the value is already a typed value — a date, a number, a GUID. Text is passed through untouched.</strong></p><p><code>{0:yyyy-MM-dd}</code> applied to the string <code>&quot;2026-03-09&quot;</code> returns <code>2026-03-09</code> unchanged; applied to the string <code>&quot;03/09/2026&quot;</code> it also returns <code>03/09/2026</code> unchanged. It is not reformatting the date — it is ignoring the specifier, because .NET strings have no formatting behavior of their own. If the output looks exactly like the input, this is almost always why.</p><p>Use this table to know what you are holding:</p><table tabindex="0"><thead><tr><th>Source</th><th>Type you get</th><th>Format specifiers apply?</th></tr></thead><tbody><tr><td><code>{PROP:Name}</code></td><td>The Common Model property&#39;s real type — <code>DateTime</code>, <code>decimal</code>, <code>bool</code>, <code>string</code></td><td>Yes, for the non-string types</td></tr><tr><td><code>{CD:Name}</code></td><td>Text (Custom Data is stored as a string)</td><td>No</td></tr><tr><td><code>{PK:Name}</code> / <code>{FK:Name}</code></td><td>Text (keys are stored as strings)</td><td>No</td></tr><tr><td><code>{RD:Name}</code></td><td>Whatever was stored on the Related Data item</td><td>Only if it was stored typed</td></tr><tr><td><code>{SESSION:Name}</code></td><td>Whatever the Get Session Values action captured</td><td>Usually text — see below</td></tr><tr><td><code>{VAR:Name}</code></td><td>The Variable&#39;s <strong>Value Type</strong>, or the generator&#39;s output</td><td>Yes, once Value Type is set</td></tr><tr><td><code>{SYS:CurrentDateTime}</code></td><td><code>DateTime</code> (UTC)</td><td>Yes — defaults to <code>O</code> if you omit a format</td></tr><tr><td><code>{SYS:DateLastPolled}</code> / <code>{SYS:EventTime}</code></td><td><code>DateTime</code></td><td>Yes — <strong>always give these an explicit format</strong></td></tr><tr><td><code>{SYS:PrimaryId}</code> / <code>{SYS:ParentId}</code></td><td>Text</td><td>No</td></tr><tr><td>Value read from a JSON payload</td><td>Newtonsoft&#39;s parsed type — an ISO-8601 string in the payload arrives as a date; <code>03/09/2026</code> arrives as text</td><td>Yes for the former, no for the latter</td></tr><tr><td>Value read from SQL</td><td>The column&#39;s SQL type</td><td>Yes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Always format your date placeholders</p><p>A <code>DateTime</code> with no format specifier renders through <code>ToString()</code>, which is <strong>culture-dependent</strong> and produces something like <code>3/9/2026 2:05:07 PM</code>. That is almost never what an API filter wants. Write <code>{SYS:DateLastPolled:O}</code> or <code>{SYS:DateLastPolled:yyyy-MM-ddTHH:mm:ssZ}</code>, not <code>{SYS:DateLastPolled}</code>.</p></div><h3 id="when-the-value-is-text-and-you-need-it-formatted" tabindex="-1">When the value is text and you need it formatted <a class="header-anchor" href="#when-the-value-is-text-and-you-need-it-formatted" aria-label="Permalink to &quot;When the value is text and you need it formatted&quot;">​</a></h3><p>Convert it to a real type first, then format. On the <a href="./datahub-data-adaptation.html#transforms-tab">Transforms</a> tab, chain a coercing transform ahead of the Formatting Template:</p><table tabindex="0"><thead><tr><th>You have</th><th>Chain</th><th>Result</th></tr></thead><tbody><tr><td><code>&quot;2026-03-09T14:05:07Z&quot;</code> as text</td><td><strong>Convert TimeZone to UTC</strong> → <strong>Formatting Template</strong> <code>{0:yyyyMMdd}</code></td><td><code>20260309</code></td></tr><tr><td><code>1430438400000</code> (epoch ms)</td><td><strong>From Epoch Time</strong> → <strong>Formatting Template</strong> <code>{0:yyyy-MM-dd}</code></td><td><code>2015-05-01</code></td></tr><tr><td>A timestamp you want as a bare date</td><td><strong>Date Only</strong> → <strong>Formatting Template</strong> <code>{0:yyyy-MM-dd}</code></td><td><code>2015-05-01</code></td></tr></tbody></table><p>For a <code>{VAR:...}</code> placeholder there is no transform chain — set the Variable&#39;s <strong>Value Type</strong> to <code>Date</code>, <code>Decimal</code>, etc. and the format specifier starts working.</p><h2 id="where" tabindex="-1">Where you can format <a class="header-anchor" href="#where" aria-label="Permalink to &quot;Where you can format {#where}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>Syntax</th><th>Notes</th></tr></thead><tbody><tr><td><a href="./datahub-endpoint-config.html#parameterizing">Parameterized placeholders</a> — URLs, bodies, file names, instruction values, lookup templates</td><td><code>{PREFIX:Name:format}</code></td><td>The format is everything after the <em>second</em> colon, up to the closing brace</td></tr><tr><td><a href="./datahub-data-adaptation.html#transforms-tab">Formatting Template transform</a></td><td><code>{0:format}</code>, <code>{1:format}</code>, …</td><td>Positional. <code>{0}</code> is the mapped value, or the first inner map of a multi-property map</td></tr><tr><td><strong>Read URL</strong> and <strong>Read Body</strong> positional arguments</td><td><code>{0:format}</code>, <code>{1:format}</code></td><td><code>{0}</code> is <code>DateLastPolled</code>, <code>{1}</code> is <code>EventTime</code> — see <a href="#positional-arguments">Positional arguments</a></td></tr><tr><td><strong>Value Type</strong> (Advanced tab)</td><td>dropdown</td><td>Conversion, <em>not</em> formatting — see <a href="#order-of-operations">Order of operations</a></td></tr><tr><td><strong>Date Format</strong> (Read action)</td><td><code>ISO</code> / <code>Unix Epoch Milliseconds</code></td><td>Applies to the read-window date before it reaches any placeholder</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Colons in a format are fine</p><p>The parser takes the first colon as the prefix separator and the second as the format separator; everything after that is the format. <code>{SYS:EventTime:yyyy-MM-ddTHH:mm:ssZ}</code> parses correctly.</p></div><h2 id="order-of-operations" tabindex="-1">Order of operations <a class="header-anchor" href="#order-of-operations" aria-label="Permalink to &quot;Order of operations {#order-of-operations}&quot;">​</a></h2><p>Formatting is one step in a fixed chain. Getting the order wrong is the second most common cause of unexpected output.</p><p><strong>On a property map (read or write):</strong></p><ol><li>The raw value is read from the source (payload, column, or Common Model property).</li><li><strong>Transforms</strong> run in list order — including Formatting Template, which produces <strong>text</strong>.</li><li><strong>Value Type</strong> conversion runs <em>after</em> all transforms.</li><li>The result is written.</li></ol><div class="warning custom-block"><p class="custom-block-title">Value Type undoes a Formatting Template</p><p>Because Value Type runs last, setting <strong>Value Type = Date</strong> on a map whose Formatting Template produced <code>03/09/2026</code> parses that text straight back into a <code>DateTime</code> and re-serializes it — discarding your formatting. If the Formatting Template is producing your final wire format, leave Value Type blank or set it to <code>String</code>.</p></div><p><strong>On a Read URL or Read Body:</strong></p><ol><li><code>{PREFIX:Name:format}</code> placeholders are resolved and formatted.</li><li>The resulting string is then run through positional <code>string.Format</code> with the read-window arguments.</li></ol><p>Both passes see the same text, which is why <a href="#escaping-braces">brace escaping</a> matters.</p><h2 id="dates" tabindex="-1">Date and time examples <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;Date and time examples {#dates}&quot;">​</a></h2><p>Against <code>2026-03-09 14:05:07 UTC</code>:</p><table tabindex="0"><thead><tr><th>Format</th><th>Output</th><th>When to use</th></tr></thead><tbody><tr><td><code>O</code></td><td><code>2026-03-09T14:05:07.0000000Z</code></td><td>Round-trip ISO 8601. The safest default, and what <code>{SYS:CurrentDateTime}</code> uses when you omit a format</td></tr><tr><td><code>s</code></td><td><code>2026-03-09T14:05:07</code></td><td>Sortable ISO without the zone — OData <code>$filter</code>, most REST query params</td></tr><tr><td><code>yyyy-MM-ddTHH:mm:ssZ</code></td><td><code>2026-03-09T14:05:07Z</code></td><td>ISO with a literal <code>Z</code>. Use when the API rejects fractional seconds</td></tr><tr><td><code>yyyy-MM-ddTHH:mm:ss.fffZ</code></td><td><code>2026-03-09T14:05:07.000Z</code></td><td>ISO with milliseconds only</td></tr><tr><td><code>yyyy-MM-dd</code></td><td><code>2026-03-09</code></td><td>Date-only filters, Salesforce/SuiteQL date literals</td></tr><tr><td><code>MM/dd/yyyy</code></td><td><code>03/09/2026</code></td><td>US-style APIs that insist on it</td></tr><tr><td><code>yyyyMMdd</code></td><td><code>20260309</code></td><td>File name stamps, fixed-width batch files</td></tr><tr><td><code>yyyyMMdd_HHmmss</code></td><td><code>20260309_140507</code></td><td>Unique file names per run</td></tr><tr><td><code>HH:mm:ss</code></td><td><code>14:05:07</code></td><td>Time-only fields</td></tr><tr><td><code>u</code></td><td><code>2026-03-09 14:05:07Z</code></td><td>Universal sortable</td></tr><tr><td><code>R</code></td><td><code>Mon, 09 Mar 2026 14:05:07 GMT</code></td><td>RFC 1123 — <code>If-Modified-Since</code> style headers</td></tr><tr><td><code>MMM d, yyyy</code></td><td><code>Mar 9, 2026</code></td><td>Human-readable, e.g. a description field or an alert body</td></tr></tbody></table><p>Worked examples:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/orders?modifiedSince={SYS:DateLastPolled:O}</span></span>
<span class="line"><span>/api/orders?$filter=lastmodifieddate ge {SYS:DateLastPolled:s}Z and lastmodifieddate lt {SYS:EventTime:s}Z</span></span>
<span class="line"><span>export_{SYS:CurrentDateTime:yyyyMMdd_HHmmss}.csv</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Epoch timestamps</p><p>There is no format specifier for Unix time. Either set the read action&#39;s <strong>Date Format</strong> to <code>Unix Epoch Milliseconds</code> (which converts the read-window date before it is injected), or use the <strong>To Epoch Time</strong> transform on a map.</p></div><div class="tip custom-block"><p class="custom-block-title">Time zones</p><p>Format strings render whatever instant they are given — they never shift it. To change the instant, use the <a href="./datahub-endpoint-config.html#time-zone-conversion">Time Zone Conversion</a> instruction (for the read-window timestamp) or the <strong>Convert UTC To TimeZone</strong> transform (for a mapped value), then format the result.</p></div><h2 id="numbers" tabindex="-1">Number examples <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Number examples {#numbers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Input</th><th>Output</th><th>When to use</th></tr></thead><tbody><tr><td><code>0.00</code></td><td><code>3.5</code></td><td><code>3.50</code></td><td>Fixed 2 decimals — money on the wire</td></tr><tr><td><code>F2</code></td><td><code>3.5</code></td><td><code>3.50</code></td><td>Same, standard-specifier spelling</td></tr><tr><td><code>0.##</code></td><td><code>3.50</code></td><td><code>3.5</code></td><td>At most 2 decimals, trailing zeros dropped</td></tr><tr><td><code>D6</code></td><td><code>42</code></td><td><code>000042</code></td><td>Zero-padded integer (integers only)</td></tr><tr><td><code>000000</code></td><td><code>42</code></td><td><code>000042</code></td><td>Zero-padded, works for any numeric type</td></tr><tr><td><code>#,##0.00</code></td><td><code>1234567.891</code></td><td><code>1,234,567.89</code></td><td>Grouped display value</td></tr><tr><td><code>P1</code></td><td><code>0.15</code></td><td><code>15.0%</code></td><td>Percentage — note it multiplies by 100</td></tr><tr><td><code>X</code></td><td><code>255</code></td><td><code>FF</code></td><td>Hexadecimal</td></tr><tr><td><code>0.00;(0.00);-</code></td><td><code>-12.3</code></td><td><code>(12.30)</code></td><td>Positive;negative;zero sections — accounting-style negatives</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Culture-dependent specifiers</p><p><code>C</code> (currency), <code>N</code>, <code>P</code>, <code>D</code>/<code>d</code>/<code>g</code> for dates, and anything relying on <code>,</code> or <code>.</code> as a separator render according to the <strong>server&#39;s</strong> culture, which you do not control per endpoint. For anything that goes on the wire, prefer an explicit custom format (<code>0.00</code>, <code>#,##0.00</code>, <code>yyyy-MM-dd</code>) over a standard specifier. Culture-dependent specifiers are fine for human-facing text such as alert bodies.</p></div><div class="tip custom-block"><p class="custom-block-title">Decimals keep their scale</p><p>With no format specifier, a <code>decimal</code> renders with its stored scale — <code>3.50</code> stays <code>3.50</code>, not <code>3.5</code>. If a target rejects trailing zeros, format it explicitly with <code>0.##</code>.</p></div><h2 id="composing" tabindex="-1">Composing values <a class="header-anchor" href="#composing" aria-label="Permalink to &quot;Composing values {#composing}&quot;">​</a></h2><p>The <a href="./datahub-data-adaptation.html#transforms-tab">Formatting Template</a> transform is the general-purpose &quot;build a string&quot; tool. On a <strong>multi-property map</strong> the inner maps arrive as <code>{0}</code>, <code>{1}</code>, <code>{2}</code> in the order they are listed; on a single-property map only <code>{0}</code> is available (and can be repeated).</p><table tabindex="0"><thead><tr><th>Template</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td><code>{0} {1}</code></td><td><code>John</code>, <code>Doe</code></td><td><code>John Doe</code></td></tr><tr><td><code>{0}-{1}-{2}</code></td><td><code>1</code>, <code>2</code>, <code>3</code></td><td><code>1-2-3</code></td></tr><tr><td><code>{2}, {1}, {0}</code></td><td><code>1</code>, <code>2</code>, <code>3</code></td><td><code>3, 2, 1</code></td></tr><tr><td><code>{0}-TC</code></td><td><code>FX-1234</code></td><td><code>FX-1234-TC</code></td></tr><tr><td><code>INV-{0:D6}</code></td><td><code>42</code></td><td><code>INV-000042</code></td></tr><tr><td><code>{0:yyyy}-{0:MM}</code></td><td><code>2026-03-09</code> (a date)</td><td><code>2026-03</code></td></tr><tr><td><code>https://…/main.aspx?…&amp;id={0}</code></td><td>a GUID</td><td>a deep link into the source system</td></tr></tbody></table><p>Notes:</p><ul><li><strong>A placeholder can be reused.</strong> <code>{0}{0}</code> is legal and repeats the value.</li><li><strong>Alignment is supported</strong>: <code>{0,10}</code> right-aligns to 10 characters, <code>{0,-10}</code> left-aligns, <code>{0,8:0.00}</code> combines alignment and format. Useful for fixed-width file output.</li><li><strong>A blank input short-circuits the transform</strong> — an empty or null value is returned unchanged rather than rendered into the template.</li><li><strong>GUIDs</strong> honor <code>{0:N}</code> (no dashes) and <code>{0:D}</code> (with dashes).</li><li>To join a <em>list</em> into one delimited string, use the <strong>String Join</strong> transform, not a Formatting Template.</li></ul><h2 id="escaping-braces" tabindex="-1">Escaping braces <a class="header-anchor" href="#escaping-braces" aria-label="Permalink to &quot;Escaping braces {#escaping-braces}&quot;">​</a></h2><p>Because Read URLs, Read Bodies, and save bodies are run through <code>string.Format</code>, a literal <code>{</code> or <code>}</code> in that text must be <strong>doubled</strong>. An unescaped brace that isn&#39;t a valid placeholder raises a <code>FormatException</code> and the action fails.</p><table tabindex="0"><thead><tr><th>You want on the wire</th><th>Write</th></tr></thead><tbody><tr><td><code>{&#39;dateFilter&#39;: 1430438400000}</code></td><td><span><code>{{&#39;dateFilter&#39;: {0}}}</code></span></td></tr><tr><td><code>select * from {catalog}.{schema}</code></td><td><span><code>select * from {{catalog}}.{{schema}}</code></span></td></tr><tr><td><code>{ orders(first: 50) { id } }</code> (GraphQL)</td><td><span><code>{{ orders(first: 50) {{ id }} }}</code></span></td></tr></tbody></table><p>This applies to <strong>any</strong> brace-heavy body — JSON, GraphQL, JSON-in-a-query-string. It does <strong>not</strong> apply to <code>{PREFIX:Name}</code> placeholders, which are resolved by the parameterizing pass and should be left single-braced.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>It also applies to a <strong>Connector Property</strong> path that contains a literal brace, since list-index maps use the <code>[{0}]</code> pattern in that same field. A column genuinely named <code>{ref}</code> is written <span><code>{{ref}}</code></span>.</p></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th></tr></thead><tbody><tr><td>The value comes out exactly as it went in, format ignored</td><td>The value is text. See <a href="#typed-values">The one rule</a> — coerce it first</td></tr><tr><td>A date renders as <code>3/9/2026 2:05:07 PM</code></td><td>No format specifier on a <code>DateTime</code> placeholder; it fell back to culture-dependent <code>ToString()</code></td></tr><tr><td>The Formatting Template output is discarded / re-serialized</td><td><strong>Value Type</strong> is set on the same map and runs after transforms — see <a href="#order-of-operations">Order of operations</a></td></tr><tr><td><code>FormatException</code> / &quot;Input string was not in a correct format&quot; on a read or save</td><td>An unescaped <code>{</code> or <code>}</code> in the URL or body — see <a href="#escaping-braces">Escaping braces</a></td></tr><tr><td>A Formatting Template errors on an index</td><td>The template references <code>{1}</code> but the map supplies only one value; use a multi-property map</td></tr><tr><td>The placeholder renders as empty</td><td>The token resolved to null — check the name and the prefix, not the format</td></tr><tr><td>The placeholder renders literally, braces and all</td><td>The prefix isn&#39;t recognized. Only <code>SYS</code>, <code>PROP</code>, <code>CD</code>, <code>PK</code>, <code>FK</code>, <code>RD</code>, <code>SESSION</code>, <code>VAR</code>, and <code>AUTH</code> are substituted</td></tr><tr><td>A format containing <code>}</code> doesn&#39;t work</td><td>Placeholder formats end at the first <code>}</code>. Use a Formatting Template transform instead</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./datahub-endpoint-config.html#parameterizing">Endpoint Configuration → Parameterizing</a> — the placeholder prefixes and where they resolve</li><li><a href="./datahub-data-adaptation.html#transforms-tab">Data Adaptation → Transforms</a> — the full transform catalog, including Formatting Template</li><li><a href="./session-values.html">Session Values</a> — capturing <code>{SESSION:...}</code> values from a response</li><li><a href="./datahub-scheduling.html">Scheduling &amp; Automation</a> — defining the Variables behind <code>{VAR:...}</code></li><li><a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/standard-date-and-time-format-strings" target="_blank" rel="noreferrer">Standard date and time format strings</a> / <a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/custom-date-and-time-format-strings" target="_blank" rel="noreferrer">custom</a> — Microsoft reference</li><li><a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/standard-numeric-format-strings" target="_blank" rel="noreferrer">Standard numeric format strings</a> / <a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/custom-numeric-format-strings" target="_blank" rel="noreferrer">custom</a> — Microsoft reference</li></ul>`,49)])])}const u=t(r,[["render",s]]);export{p as __pageData,u as default};
